mapper.update:

           UPDATE CAA100
              SET     RQST_PRCS_SRVC_INST_NO   =    #{RQST_PRCS_SRVC_INST_NO}
					, PIC_NM                   =    REGEXP_REPLACE(#{PRCS_PIC_NM},'[\n\r\t|]+', '')
					, PIC_TELNO                =    REGEXP_REPLACE(#{PRCS_PIC_TELNO},'[\n\r\t|]+', '')
					, RCPT_SE_CD               =    #{RCPT_SE_CD}
					, RQST_PRCS_YMD            =    REGEXP_REPLACE(#{RQST_PRCS_YMD},'[\n\r\t|]+', '')
					, PRCS_YMD                 =    REGEXP_REPLACE(#{PRCS_YMD},'[\n\r\t|]+', '')
					, RJCT_CS_CN               =    REGEXP_REPLACE(#{RJCT_CS_CN},'[\n\r\t|]+', '')
            WHERE SRVC_RQST_APLY_NO = #{SRVC_RQST_APLY_NO}



       MERGE INTO
        CAA100 T1
        USING DUAL
           ON (T1.SRVC_RQST_APLY_NO    = #{SRVC_RQST_APLY_NO})
         WHEN MATCHED THEN
            UPDATE SET
	            T1.PRCS_YMD                            = #{PRCS_YMD}
	          , T1.RCPT_SE_CD                          = #{RCPT_SE_CD}
	          , T1.PIC_TELNO                           = #{PRCS_PIC_TELNO}
	          , T1.PIC_NM                              = #{PRCS_PIC_NM}
	          , T1.RQST_PRCS_SRVC_INST_NO              = #{RQST_PRCS_SRVC_INST_NM}
	          , T1.RJCT_CS_CN                          = #{RJCT_CS_CN}

         WHEN NOT MATCHED THEN

            INSERT
           (  T1.SRVC_RQST_APLY_NO      /* 서비스의뢰신청번호 */
	    	, T1.TRPR_RRNO              /* 대상자주민등록번호 */
			, T1.TRPR_NM                /* 대상자명 */
			, T1.RQST_PRCS_SRVC_INST_NO /* 처리기관명 */
			, T1.PIC_NM                 /* 담당자 */
			, T1.PIC_TELNO              /* 담당자연락처 */
			, T1.RCPT_SE_CD             /* 접수구분코드 */
			, T1.RQST_PRCS_YMD          /* 접수일자 */
			, T1.PRCS_YMD               /* 처리일자 */
    		, T1.RJCT_CS_CN             /* 반려사유내용 */
    		, T1.ESB_STATUS             /* 연계상태 */
    		, T1.ESB_SEQ                /* 연계시퀀스 */
    		, T1.SND_CD                 /* 송신기관번호 */
    		, T1.RCV_CD                 /* 수신기관번호 */
    		, T1.CREATE_TIME            /* 데이터생성일시 */
            )
            VALUES
            (
			  #{SRVC_RQST_APLY_NO}
			, #{TRPR_RRNO}
			, #{TRPR_NM}
			, #{RQST_PRCS_SRVC_INST_NM}
			, #{PRCS_PIC_NM}
			, #{PRCS_PIC_TELNO}
			, #{RCPT_SE_CD}
			, #{RQST_PRCS_YMD}
			, #{PRCS_YMD}
			, REGEXP_REPLACE(#{RJCT_CS_CN}, '[\n\r\t|]+', '')
            , 'N'
            ,  ( SELECT /*+ INDEX_DESC(T1 INDEX1) */
                   NVL(MAX(T1.ESB_SEQ),0) + 1
              FROM CAA100 T1 )
            , 'MOG'
            , 'MMA'
            , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISSFF3')
            )


UPDATE CAA130
   SET ESB_STATUS = 'Y'
 WHERE SRVC_RQST_APLY_NO = #{SRVC_RQST_APLY_NO}

